                    else update public.posts set downs = downs + 1 where id = new.post_id; end if;
  elsif (tg_op = 'DELETE') then
    if old.value = 1 then update public.posts set ups = ups - 1 where id = old.post_id;
                    else update public.posts set downs = downs - 1 where id = old.post_id; end if;
  elsif (tg_op = 'UPDATE' and new.value <> old.value) then
    if old.value = 1 then update public.posts set ups = ups - 1 where id = new.post_id;
                    else update public.posts set downs = downs - 1 where id = new.post_id; end if;
    if new.value = 1 then update public.posts set ups = ups + 1 where id = new.post_id;
                    else update public.posts set downs = downs + 1 where id = new.post_id; end if;
  end if;
  return null;
end; $$;


