CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m jsonb; base text; uname text; disp text; av text;
begin
  m := coalesce(new.raw_user_meta_data,'{}'::jsonb);
  disp := coalesce(nullif(m->>'full_name',''), nullif(m->>'name',''), nullif(split_part(coalesce(new.email,''),'@',1),''));
  av   := coalesce(nullif(m->>'avatar_url',''), nullif(m->>'picture',''));
  base := lower(regexp_replace(
            coalesce(nullif(split_part(coalesce(new.email,''),'@',1),''), disp, 'user'),
            '[^a-z0-9]+','','g'));
  if base = '' then base := 'user'; end if;
  uname := base;
  if exists (select 1 from public.profiles where username = uname) then
    uname := base || substr(replace(new.id::text,'-',''),1,6);
  end if;
  insert into public.profiles (id, username, display_name, avatar_url)
  values (new.id, uname, disp, av);
  return new;
end; $$;


