--
-- Name: moderation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  j jsonb := to_jsonb(new);
  v text;
begin
  v := public.moderation_violation(
         concat_ws(' ',
           coalesce(j->>'title',''),
           coalesce(j->>'body',''),
           coalesce(j->>'name',''),
           coalesce(j->>'blurb','')
         ));

  if v is not null then
    raise exception 'MODERATION_BLOCKED_%', upper(v)
      using errcode = 'P0001',
            hint = 'Submission rejected by content policy.';
  end if;

  return new;
end $$;


--
-- Name: moderation_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_normalize(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select regexp_replace(
           translate(lower(coalesce(txt,'')),
                     '4310$@!', 'aeiosai'),
           '[^a-z0-9]+', ' ', 'g');
$_$;


--
-- Name: moderation_squash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_squash(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(public.moderation_normalize(txt), '\s+', '', 'g');
$$;


--
-- Name: moderation_violation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_violation(txt text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  norm    text := public.moderation_normalize(txt);
  squash  text := public.moderation_squash(txt);
  allowed text;
  hit     record;
begin
  if txt is null or length(trim(txt)) = 0 then
    return null;
  end if;

  -- strip allowlisted phrases first so they can't trip a substring match
  for allowed in select public.moderation_normalize(phrase) from public.moderation_allowlist loop
    norm   := replace(norm, allowed, ' ');
    squash := replace(squash, replace(allowed,' ',''), '');
  end loop;

  -- whole-word match on the normalised text (low false-positive)
  for hit in select term, category from public.moderation_terms loop
    if norm ~ ('\m' || regexp_replace(hit.term, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '\M') then
      return hit.category;
    end if;
  end loop;

  -- substring match on squashed text, strict terms only (catches f u c k)
  for hit in select term, category from public.moderation_terms where strict loop
    if position(replace(hit.term,' ','') in squash) > 0 then
      return hit.category;
    end if;
  end loop;

  return null;
end $_$;


