-- Name: posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    author_id uuid DEFAULT auth.uid(),
    title text NOT NULL,
    body text,
    type public.content_type DEFAULT 'take'::public.content_type NOT NULL,
    place_id uuid,
    ups integer DEFAULT 0 NOT NULL,
    downs integer DEFAULT 0 NOT NULL,
    score integer GENERATED ALWAYS AS ((ups - downs)) STORED,
    comment_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    city_id uuid,
    submitted_city text,
    submitted_region text,
    submitted_country text,
    city_match boolean,
    status public.moderation_status DEFAULT 'approved'::public.moderation_status NOT NULL,
    moderated_at timestamp with time zone,
    moderated_by uuid,
    moderation_note text,
    months smallint[],
    place_label text,
    author_verified boolean DEFAULT false NOT NULL,
    topic text,
    question_id uuid,
    CONSTRAINT posts_body_len CHECK (((body IS NULL) OR (char_length(body) <= 2000))),
    CONSTRAINT posts_months_valid CHECK (((months IS NULL) OR ((months <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint, (8)::smallint, (9)::smallint, (10)::smallint, (11)::smallint, (12)::smallint]) AND ((cardinality(months) >= 1) AND (cardinality(months) <= 12))))),
    CONSTRAINT posts_place_label_check CHECK (((place_label IS NULL) OR (char_length(place_label) <= 60))),
    CONSTRAINT posts_title_len CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200))),
    CONSTRAINT posts_topic_check CHECK (((topic IS NULL) OR ((char_length(topic) >= 3) AND (char_length(topic) <= 120))))
);


--
-- Name: COLUMN posts.submitted_city; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.posts.submitted_city IS 'Coarse city from Cloudflare request.cf at submit time. Advisory signal only.';


--
-- Name: cities_with_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cities_with_counts WITH (security_invoker='true') AS
 SELECT c.id,
    c.name,
    c.state,
    c.slug,
    c.lat,
    c.lng,
    c.blurb,
    c.sort,
    COALESCE(pc.place_count, (0)::bigint) AS place_count,
    COALESCE(tc.take_count, (0)::bigint) AS take_count,
    c.photo
   FROM ((public.cities c
     LEFT JOIN ( SELECT p.city,
            count(*) AS place_count
           FROM public.places p
          WHERE (p.city IS NOT NULL)
          GROUP BY p.city) pc ON ((pc.city = c.name)))
     LEFT JOIN ( SELECT po.city_id,
            count(*) AS take_count
           FROM public.posts po
          WHERE (po.status = 'approved'::public.moderation_status)
          GROUP BY po.city_id) tc ON ((tc.city_id = c.id)));


