    severity public.event_severity DEFAULT 'busy'::public.event_severity NOT NULL,
    start_month smallint NOT NULL,
    end_month smallint NOT NULL,
    author_id uuid DEFAULT auth.uid(),
    ups integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    status public.moderation_status DEFAULT 'approved'::public.moderation_status NOT NULL,
    source text,
    verified_at timestamp with time zone,
    check_note text,
    CONSTRAINT city_events_blurb_len CHECK (((blurb IS NULL) OR (char_length(blurb) <= 400))),
    CONSTRAINT city_events_end_month_check CHECK (((end_month >= 1) AND (end_month <= 12))),
    CONSTRAINT city_events_name_len CHECK (((char_length(name) >= 1) AND (char_length(name) <= 120))),
    CONSTRAINT city_events_source_len CHECK (((source IS NULL) OR (char_length(source) <= 500))),
    CONSTRAINT city_events_start_month_check CHECK (((start_month >= 1) AND (start_month <= 12)))
);


--
-- Name: city_founders; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.city_founders WITH (security_invoker='true') AS
 SELECT city_id,
    author_id,
    first_post,
    rank
   FROM ( SELECT posts.city_id,
            posts.author_id,
            min(posts.created_at) AS first_post,
            row_number() OVER (PARTITION BY posts.city_id ORDER BY (min(posts.created_at))) AS rank
           FROM public.posts
          WHERE (posts.author_verified AND (posts.status = 'approved'::public.moderation_status) AND (posts.author_id IS NOT NULL))
          GROUP BY posts.city_id, posts.author_id) x
  WHERE (rank <= 10);


--
-- Name: city_request_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.city_request_counts WITH (security_invoker='true') AS
 SELECT slug,
    name,
    state,
    pop_rank,
    requests
   FROM public.city_candidates c
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.cities x
          WHERE (x.slug = c.slug))));


